  1707  void BinaryReaderObjdump::PrintInitExpr(const InitExpr& expr) {
  1708    assert(expr.insts.size() > 0);
  1709
  1710    // We have two different way to print init expressions.  One for
  1711    // extended expressions involving more than one instruction, and
  1712    // a short form for the more traditional single instruction form.
  1713    if (expr.insts.size() > 1) {
  1714      PrintDetails(" - init (");
  1715      bool first = true;
  1716      for (auto& inst : expr.insts) {
  1717        if (!first) {
  1718          PrintDetails(", ");
  1719        }
  1720        first = false;
  1721        PrintDetails("%s", inst.opcode.GetName());
  1722        switch (inst.opcode) {
  1723          case Opcode::I32Const:
  1724            PrintDetails(" %d", inst.imm.i32);
  1725            break;
  1726          case Opcode::I64Const:
  1727            PrintDetails(" %" PRId64, inst.imm.i64);
  1728            break;
  1729          case Opcode::F32Const: {
  1730            char buffer[WABT_MAX_FLOAT_HEX];
  1731            WriteFloatHex(buffer, sizeof(buffer), inst.imm.f32);
  1732            PrintDetails(" %s\n", buffer);
  1733            break;
  1734          }
  1735          case Opcode::F64Const: {
  1736            char buffer[WABT_MAX_DOUBLE_HEX];
  1737            WriteDoubleHex(buffer, sizeof(buffer), inst.imm.f64);
  1738            PrintDetails(" %s\n", buffer);
  1739            break;
  1740          }
  1741          case Opcode::GlobalGet: {
  1742            PrintDetails(" %" PRIindex, inst.imm.index);
  1743            std::string_view name = GetGlobalName(inst.imm.index);
  1744            if (!name.empty()) {
  1745              PrintDetails(" <" PRIstringview ">",
  1746                           WABT_PRINTF_STRING_VIEW_ARG(name));
  1747            }
  1748            break;
  1749          }
  1750          default:
  1751            break;
  1752        }
  1753      }
  1754      PrintDetails(")\n");
  1755      return;
  1756    }
  1757
  1758    switch (expr.type) {
  1759      case InitExprType::I32:
  1760        PrintDetails(" - init i32=%d\n", expr.insts[0].imm.i32);
  1761        break;
  1762      case InitExprType::I64:
  1763        PrintDetails(" - init i64=%" PRId64 "\n", expr.insts[0].imm.i64);
  1764        break;
  1765      case InitExprType::F64: {
  1766        char buffer[WABT_MAX_DOUBLE_HEX];
  1767        WriteDoubleHex(buffer, sizeof(buffer), expr.insts[0].imm.f64);
  1768        PrintDetails(" - init f64=%s\n", buffer);
  1769        break;
  1770      }
  1771      case InitExprType::F32: {
  1772        char buffer[WABT_MAX_FLOAT_HEX];
  1773        WriteFloatHex(buffer, sizeof(buffer), expr.insts[0].imm.f32);
  1774        PrintDetails(" - init f32=%s\n", buffer);
  1775        break;
  1776      }
  1777      case InitExprType::V128: {
  1778        PrintDetails(
  1779            " - init v128=0x%08x 0x%08x 0x%08x 0x%08x \n",
  1780            expr.insts[0].imm.v128_v.u32(0), expr.insts[0].imm.v128_v.u32(1),
  1781            expr.insts[0].imm.v128_v.u32(2), expr.insts[0].imm.v128_v.u32(3));
  1782        break;
  1783      }
  1784      case InitExprType::Global: {
  1785        PrintDetails(" - init global=%" PRIindex, expr.insts[0].imm.index);
  1786        std::string_view name = GetGlobalName(expr.insts[0].imm.index);
  1787        if (!name.empty()) {
  1788          PrintDetails(" <" PRIstringview ">", WABT_PRINTF_STRING_VIEW_ARG(name));
  1789        }
  1790        PrintDetails("\n");
  1791        break;
  1792      }
  1793      case InitExprType::FuncRef: {
  1794        PrintDetails(" - init ref.func:%" PRIindex, expr.insts[0].imm.index);
  1795        std::string_view name = GetFunctionName(expr.insts[0].imm.index);
  1796        if (!name.empty()) {
  1797          PrintDetails(" <" PRIstringview ">", WABT_PRINTF_STRING_VIEW_ARG(name));
  1798        }
  1799        PrintDetails("\n");
  1800        break;
  1801      }
  1802      case InitExprType::NullRef:
  1803        PrintDetails(" - init null\n");
  1804        break;
  1805        break;
  1806    }
  1807  }
