  2657  Result BinaryReader::ReadElemSection(Offset section_size) {
  2658    CALLBACK(BeginElemSection, section_size);
  2659    Index num_elem_segments;
  2660    CHECK_RESULT(ReadCount(&num_elem_segments, "elem segment count"));
  2661    CALLBACK(OnElemSegmentCount, num_elem_segments);
  2662    for (Index i = 0; i < num_elem_segments; ++i) {
  2663      uint32_t flags;
  2664      CHECK_RESULT(ReadU32Leb128(&flags, "elem segment flags"));
  2665      ERROR_IF(flags > SegFlagMax, "invalid elem segment flags: %#x", flags);
  2666      Index table_index(0);
  2667      if ((flags & (SegPassive | SegExplicitIndex)) == SegExplicitIndex) {
  2668        CHECK_RESULT(ReadIndex(&table_index, "elem segment table index"));
  2669      }
  2670      Type elem_type = Type::FuncRef;
  2671
  2672      CALLBACK(BeginElemSegment, i, table_index, flags);
  2673
  2674      if (!(flags & SegPassive)) {
  2675        CALLBACK(BeginElemSegmentInitExpr, i);
  2676        CHECK_RESULT(ReadInitExpr(i));
  2677        CALLBACK(EndElemSegmentInitExpr, i);
  2678      }
  2679
  2680      // For backwards compat we support not declaring the element kind.
  2681      if (flags & (SegPassive | SegExplicitIndex)) {
  2682        if (flags & SegUseElemExprs) {
  2683          CHECK_RESULT(ReadRefType(&elem_type, "table elem type"));
  2684        } else {
  2685          ExternalKind kind;
  2686          CHECK_RESULT(ReadExternalKind(&kind, "export kind"));
  2687          ERROR_UNLESS(kind == ExternalKind::Func,
  2688                       "segment elem type must be func (%s)",
  2689                       elem_type.GetName().c_str());
  2690          elem_type = Type::FuncRef;
